function can(user, permission){ const p=permissions[user?.role]||[]; return p.includes('*')||p.includes(permission); }
function apiRequest(path, options={}){
  const headers={...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})};
  const csrf=localStorage.getItem('chw_csrf'); const token=localStorage.getItem('chw_token');
  if(token) headers['Authorization']=`Bearer ${token}`;
  if(csrf && ['POST','PUT','PATCH','DELETE'].includes((options.method||'GET').toUpperCase())) headers['X-CSRF-Token']=csrf;
  return fetch(`${API_BASE}${path}`,{...options,headers,credentials:'include'}).then(async r=>{let body=null;try{body=await r.json()}catch{} if(!r.ok) throw new Error(body?.error||body?.message||`Request failed (${r.status})`); return body||{};});
}
