  <div className="activity-stat-grid">{stats.map(([label,value])=><div className="stat-card" key={label}><span>{label}</span><strong>{busy?'—':value}</strong><small>{busy?'Loading authorized records':`Across ${data.length} ${noun}`}</small></div>)}</div>
